package com.trackermaster.core.data.money

import androidx.room.Room
import androidx.test.core.app.ApplicationProvider
import com.trackermaster.core.database.MoneyDatabaseCallback
import com.trackermaster.core.database.TrackermasterDatabase
import com.trackermaster.core.domain.model.AccountType
import com.trackermaster.core.domain.money.*
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.test.runTest
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config
import java.time.LocalDate

@RunWith(RobolectricTestRunner::class) @Config(sdk=[28])
class MoneyInvestmentRepositoryTest {
    private lateinit var db:TrackermasterDatabase
    private lateinit var money:MoneyRepository
    private lateinit var repo:MoneyInvestmentRepository
    private val day=LocalDate.of(2026,10,1)
    private val position=MoneyInvestment("fund","Fund","COP",2,day,Money(0,"COP"),Money(0,"COP"))
    @Before fun before(){db=Room.inMemoryDatabaseBuilder(ApplicationProvider.getApplicationContext(),TrackermasterDatabase::class.java).addCallback(MoneyDatabaseCallback).allowMainThreadQueries().build();money=MoneyRepository(db);repo=MoneyInvestmentRepository(db,money)}
    @After fun after(){db.close()}
    private suspend fun account(code:String="COP",space:Long=2)=money.createAccount("Cash",AccountType.CHECKING,Money(100000,code),space)
    private fun event(kind:InvestmentEventKind=InvestmentEventKind.CONTRIBUTION,amount:Long=20000,cost:Long=amount,id:String="request")=InvestmentEvent(id,"fund",kind,Money(amount,"COP"),day.plusDays(1),Money(cost,"COP"))
    private fun cash(account:Long,amount:Long=20000,direction:MoneyDirection=MoneyDirection.EXPENSE)=MoneyMovement(accountId=account,amount=Money(amount,"COP"),direction=direction,date=day.plusDays(1),spaceId=2,note="Receipt")
    private suspend fun fails(block:suspend()->Unit){try{block();fail("Expected rejection")}catch(_:IllegalArgumentException){}}
    @Test fun existingHoldingDoesNotInventCash()=runTest{account();repo.create(position.copy(initialCost=Money(30000,"COP"),initialValue=Money(35000,"COP")));assertEquals(100000L,money.snapshot().accounts.single().total.minorUnits);assertTrue(db.moneyDao().readLedger().moneyMovements().isEmpty())}
    @Test fun contributionAndVersionCommitWithCashExactlyOnce()=runTest{val a=account();repo.create(position);repo.record("fund",0,event(),cash(a));repo.record("fund",0,event(),cash(a));assertEquals(80000L,money.snapshot().accounts.single().total.minorUnits);assertEquals(1,repo.data.first().events.size);assertEquals(1L,repo.data.first().positions.single().version);assertEquals(0L,MoneyLedger.periodTotals(db.moneyDao().readLedger().moneyMovements(),"COP",day,day.plusDays(4)).expenses.minorUnits)}
    @Test fun insufficientFundsRollBackEverything()=runTest{val a=account();repo.create(position);fails{repo.record("fund",0,event(amount=100001),cash(a,100001))};assertEquals(100000L,money.snapshot().accounts.single().total.minorUnits);assertTrue(repo.data.first().events.isEmpty());assertEquals(0L,repo.data.first().positions.single().version)}
    @Test fun reusedRequestWithChangedFundingIsRejected()=runTest{val a=account();val b=account();repo.create(position);repo.record("fund",0,event(),cash(a));fails{repo.record("fund",0,event(),cash(b))};assertEquals(1,repo.data.first().events.size)}
    @Test fun valuationDoesNotTouchCash()=runTest{account();repo.create(position);repo.record("fund",0,event(InvestmentEventKind.VALUATION,30000));assertEquals(100000L,money.snapshot().accounts.single().total.minorUnits);assertTrue(db.moneyDao().readLedger().moneyMovements().isEmpty());assertEquals(30000L,InvestmentRules.progress(repo.data.first().positions.single(),repo.data.first().events,day.plusDays(3)).value.minorUnits)}
    @Test fun withdrawalSeparatesRealizedProfitFromOperatingFlow()=runTest{val a=account();repo.create(position.copy(initialCost=Money(20000,"COP"),initialValue=Money(25000,"COP")));repo.record("fund",0,event(InvestmentEventKind.WITHDRAWAL,25000,20000),cash(a,25000,MoneyDirection.INCOME));val b=repo.data.first();assertEquals(5000L,InvestmentRules.progress(b.positions.single(),b.events,day.plusDays(3)).realized.minorUnits);assertEquals(125000L,money.snapshot().accounts.single().total.minorUnits);assertEquals(0L,MoneyLedger.periodTotals(db.moneyDao().readLedger().moneyMovements(),"COP",day,day.plusDays(4)).income.minorUnits)}
    @Test fun dividendIsRealCashIncomeWithoutIncreasingAsset()=runTest{val a=account();money.ensureCategories();repo.create(position);val cat=money.observeCategories().first().first{it.isIncome};repo.record("fund",0,event(InvestmentEventKind.DIVIDEND,1000),cash(a,1000,MoneyDirection.INCOME).copy(categoryId=cat.id));assertEquals(101000L,money.snapshot().accounts.single().total.minorUnits);val b=repo.data.first();assertEquals(0L,InvestmentRules.progress(b.positions.single(),b.events,day.plusDays(3)).value.minorUnits);assertEquals(1000L,MoneyLedger.periodTotals(db.moneyDao().readLedger().moneyMovements(),"COP",day,day.plusDays(3)).income.minorUnits)}
    @Test fun linkingReceiptDoesNotChargeCashAgainAndReversePreservesReceipt()=runTest{val a=account();money.ensureCategories();val cat=money.observeCategories().first().first{!it.isIncome};val movement=cash(a).copy(categoryId=cat.id,attachmentPath="money/receipts/receipt.pdf");val id=money.record(movement);repo.create(position);repo.record("fund",0,event(),movement,linked=id);assertEquals(80000L,money.snapshot().accounts.single().total.minorUnits);assertTrue(db.moneyDao().movement(id)!!.investmentCapital);repo.reverse(repo.data.first().events.single().sequence,1);assertNotNull(db.moneyDao().movement(id));assertNull(db.moneyDao().movement(id)!!.investmentId);assertEquals("money/receipts/receipt.pdf",db.moneyDao().movement(id)!!.imageUri);assertEquals(80000L,money.snapshot().accounts.single().total.minorUnits)}
    @Test fun historyCannotEditOrDeleteLinkedInvestmentMovement()=runTest{val a=account();repo.create(position);repo.record("fund",0,event(),cash(a));val id=repo.data.first().events.single().movementId!!;fails{money.deleteEntry(id)};fails{money.record(cash(a).copy(id=id,categoryId=1))};assertNotNull(db.moneyDao().movement(id))}
    @Test fun staleVersionDoesNotCreateAnotherMovement()=runTest{val a=account();repo.create(position);repo.record("fund",0,event(),cash(a));fails{repo.record("fund",0,event(id="second"),cash(a))};assertEquals(1,repo.data.first().events.size)}
    @Test fun currencyAndPurposeMismatchLeaveNoCashMovement()=runTest{val a=account("USD",5);repo.create(position);fails{repo.record("fund",0,event(),cash(a))};assertTrue(repo.data.first().events.isEmpty());assertEquals(100000L,money.snapshot().accounts.single().total.minorUnits)}
    @Test fun reversingContributionRevalidatesLaterWithdrawals()=runTest{val a=account();repo.create(position);repo.record("fund",0,event(),cash(a));repo.record("fund",1,event(InvestmentEventKind.WITHDRAWAL,10000,10000,"out"),cash(a,10000,MoneyDirection.INCOME));val first=repo.data.first().events.first{it.id=="request"};fails{repo.reverse(first.sequence,2)};assertEquals(2,repo.data.first().events.size);assertEquals(90000L,money.snapshot().accounts.single().total.minorUnits)}
    @Test fun reversingNewContributionRestoresCashAndAsset()=runTest{val a=account();repo.create(position);repo.record("fund",0,event(),cash(a));repo.reverse(repo.data.first().events.single().sequence,1);assertEquals(100000L,money.snapshot().accounts.single().total.minorUnits);assertTrue(repo.data.first().events.isEmpty())}
    @Test fun archiveRequiresNoRemainingCostOrValue()=runTest{repo.create(position.copy(initialCost=Money(1,"COP")));fails{repo.details("fund",0,"Fund","",true)};assertFalse(repo.data.first().positions.single().archived)}
    @Test fun pocketPurposeOverridesItsBankPurpose()=runTest{val a=account();val p=money.createPocket(a,4,"Savings");money.transfer(a,a,Money(30000,"COP"),sourcePocketId=null,targetPocketId=p,requestId="reserve");repo.create(position.copy(spaceId=4));repo.record("fund",0,event(),cash(a).copy(spaceId=4,pocketId=p));assertEquals(10000L,money.snapshot().pockets.single().balance.minorUnits)}
    @Test fun openingCorrectionDoesNotInventOrRemoveCash()=runTest{account();repo.create(position.copy(initialCost=Money(20000,"COP"),initialValue=Money(25000,"COP")));repo.details("fund",0,"Corrected","",false,Money(30000,"COP"),Money(35000,"COP"),day.minusDays(1));val p=repo.data.first().positions.single();assertEquals(30000L,p.initialCost.minorUnits);assertEquals(35000L,p.initialValue.minorUnits);assertEquals(day.minusDays(1),p.opened);assertEquals(1L,p.version);assertEquals(100000L,money.snapshot().accounts.single().total.minorUnits);assertTrue(db.moneyDao().readLedger().moneyMovements().isEmpty())}
    @Test fun openingCorrectionRevalidatesCostAlreadyRecovered()=runTest{val a=account();repo.create(position.copy(initialCost=Money(20000,"COP"),initialValue=Money(25000,"COP")));repo.record("fund",0,event(InvestmentEventKind.WITHDRAWAL,10000,15000),cash(a,10000,MoneyDirection.INCOME));fails{repo.details("fund",1,"Fund","",false,Money(10000,"COP"))};assertEquals(20000L,repo.data.first().positions.single().initialCost.minorUnits);assertEquals(1L,repo.data.first().positions.single().version);assertEquals(110000L,money.snapshot().accounts.single().total.minorUnits)}
    @Test fun openingCorrectionPreservesLaterValuations()=runTest{repo.create(position.copy(initialCost=Money(20000,"COP"),initialValue=Money(25000,"COP")));repo.record("fund",0,event(InvestmentEventKind.VALUATION,30000));repo.details("fund",1,"Fund","",false,Money(30000,"COP"),Money(35000,"COP"));val b=repo.data.first();val p=InvestmentRules.progress(b.positions.single(),b.events,day.plusDays(2));assertEquals(30000L,p.value.minorUnits);assertEquals(30000L,p.cost.minorUnits);assertEquals(1,b.events.size)}
    @Test fun openingCorrectionRejectsAnotherCurrency()=runTest{repo.create(position);fails{repo.details("fund",0,"Fund","",false,Money(100,"USD"))};assertEquals(0L,repo.data.first().positions.single().version)}
}
